mapper.insert:
insert into DIS_PROD_AGENCY (AGENCY_ID,PROD_ID, CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME, CREATE_DEPT) select A.* from (
select #{item.agencyId,jdbcType=VARCHAR} AGENCY_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT from dual
)A

mapper.select:
select AGENCY_ID agencyId, AGENCY_NAME agencyName, PROD_ID prodId, PROD_NAME prodName, PROD_SERIES prodSeries, UPDATE_USER updateUser, UPDATE_TIME updateTime, TO_CHAR(UPDATE_TIME,'YYYY-MM-DD HH24:MI:SS') updateTimeStr from DIS_PROD_AGENCY
AND AGENCY_ID in
#{item}
AND PROD_SERIES in
#{item}

select count(1) count
from DIS_SALE_AGENCY
where AGENCY_NAME=#{agencyName,jdbcType=VARCHAR}

select PROD_ID id, nvl(PROD_NAME,PROD_ABBR) text from V_REP_PROD_INFO where 1=1
and STATUS=#{dataStatus,jdbcType=VARCHAR}
and (PROD_ID like concat(concat('%',#{search}),'%') or PROD_NAME like concat(concat('%',#{search}),'%'))

select distinct PROD_SERIES from REP_PROD_INFO
STATUS='E'
and PD_STATUS=#{prodStatus,jdbcType=VARCHAR}
and ISSUING_WAY=#{issueType,jdbcType=VARCHAR}
order by PROD_SERIES
